import type { ReactNode, CSSProperties } from 'react';
import { RiAmazonFill, RiAppleFill, RiDiscordFill, RiDropboxFill, RiFacebookFill, RiFigmaFill, RiGithubFill, RiGitlabFill, RiGlobalLine, RiGoogleFill, RiInstagramFill, RiLinkedinFill, RiMicrosoftFill, RiNotionFill, RiRedditFill, RiSlackFill, RiSpotifyFill, RiTelegramFill, RiTiktokFill, RiTwitchFill, RiTwitterXFill, RiWhatsappFill } from '@remixicon/react';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

const providers: Record<string, { label: string; color: string; icon?: IconComponent }> = {
  google: { label: 'Google', color: '#2678f5', icon: RiGoogleFill },
  apple: { label: 'Apple', color: '#111318', icon: RiAppleFill },
  github: { label: 'GitHub', color: '#111318', icon: RiGithubFill },
  gitlab: { label: 'GitLab', color: '#e96e30', icon: RiGitlabFill },
  microsoft: { label: 'Microsoft', color: '#4e6f98', icon: RiMicrosoftFill },
  x: { label: 'X', color: '#111318', icon: RiTwitterXFill },
  facebook: { label: 'Facebook', color: '#1877f2', icon: RiFacebookFill },
  linkedin: { label: 'LinkedIn', color: '#0a66c2', icon: RiLinkedinFill },
  discord: { label: 'Discord', color: '#5865f2', icon: RiDiscordFill },
  slack: { label: 'Slack', color: '#5b285f', icon: RiSlackFill },
  figma: { label: 'Figma', color: '#9b4cee', icon: RiFigmaFill },
  notion: { label: 'Notion', color: '#111318', icon: RiNotionFill },
  dropbox: { label: 'Dropbox', color: '#0061fe', icon: RiDropboxFill },
  spotify: { label: 'Spotify', color: '#16883b', icon: RiSpotifyFill },
  twitch: { label: 'Twitch', color: '#9146ff', icon: RiTwitchFill },
  reddit: { label: 'Reddit', color: '#ff4500', icon: RiRedditFill },
  tiktok: { label: 'TikTok', color: '#111318', icon: RiTiktokFill },
  instagram: { label: 'Instagram', color: '#d62976', icon: RiInstagramFill },
  telegram: { label: 'Telegram', color: '#229ed9', icon: RiTelegramFill },
  whatsapp: { label: 'WhatsApp', color: '#138c4a', icon: RiWhatsappFill },
  amazon: { label: 'Amazon', color: '#e48619', icon: RiAmazonFill },
  bitbucket: { label: 'Bitbucket', color: '#0052cc' },
  auth0: { label: 'Auth0', color: '#d95225' },
  okta: { label: 'Okta', color: '#007dc1' },
};

export type SocialProvider = keyof typeof providers;
export type SocialButtonProps = {
  provider?: SocialProvider;
  label?: string;
  logo?: ReactNode;
  color?: string;
  appearance?: 'brand' | 'neutral' | 'outline';
  size?: 'medium' | 'small';
  iconOnly?: boolean;
  href?: string;
  onPress?: () => void;
  disabled?: boolean;
  className?: string;
};

export function SocialButton({ provider = 'google', label, logo, color, appearance = 'outline', size = 'medium', iconOnly = false, href, onPress, disabled = false, className }: SocialButtonProps) {
  const config = providers[provider];
  const name = label ?? config?.label ?? provider;
  const Icon = config?.icon;
  const style = { '--social-brand': color ?? config?.color ?? 'var(--accent-strong)' } as CSSProperties;
  const content = <>{logo ?? (Icon ? <Icon size={size === 'small' ? 17 : 19} aria-hidden /> : <span className="ui-social-button__monogram" aria-hidden="true">{name[0]}</span>)}{!iconOnly && <span>Continue with {name}</span>}</>;
  const common = { className: cx('ui-social-button', className), 'data-appearance': appearance, 'data-size': size, 'data-icon-only': iconOnly || undefined, style, 'aria-label': iconOnly ? `Continue with ${name}` : undefined };
  return href && !disabled ? <a {...common} href={href} onClick={onPress}>{content}</a> : <button {...common} type="button" disabled={disabled} onClick={onPress}>{content}</button>;
}

export const socialProviderNames = Object.keys(providers) as SocialProvider[];

export function SocialMark({ provider, size = 14, className }: { provider?: SocialProvider; size?: number; className?: string }) {
  const config = provider ? providers[provider] : undefined;
  const Icon = config?.icon ?? RiGlobalLine;
  const monochrome = provider === 'x' || provider === 'github' || provider === 'notion' || provider === 'apple' || provider === 'tiktok';
  return <Icon size={size} className={className} style={{ color: monochrome ? 'var(--text-main)' : config?.color ?? 'var(--text-muted)' }} aria-hidden />;
}

'use client';

import { useEffect, useState } from 'react';
import { cx } from '@/utils/cx';

export type AgentThinkingProps = {
  variant?: 'wave' | 'spin' | 'stars' | 'infinity' | 'orb';
  label?: string;
  active?: boolean;
  showTimer?: boolean;
  shimmer?: boolean;
  tone?: 'subtle' | 'accent';
  className?: string;
};

const orbitOrder = [0, 1, 2, 7, -1, 3, 6, 5, 4];

function ThinkingIndicator({ variant }: { variant: NonNullable<AgentThinkingProps['variant']> }) {
  if (variant === 'wave' || variant === 'spin') {
    return <span className="ui-agent-thinking__dots">{Array.from({ length: 9 }, (_, index) => <i key={index} style={{ animationDelay: variant === 'wave' ? `${(Math.floor(index / 3) + index % 3) * 95}ms` : `${orbitOrder[index] * -165}ms` }} />)}</span>;
  }
  if (variant === 'stars') return <span className="ui-agent-thinking__stars">{Array.from({ length: 5 }, (_, index) => <i key={index} style={{ animationDelay: `${index * -320}ms` }} />)}</span>;
  if (variant === 'infinity') return <svg className="ui-agent-thinking__infinity" viewBox="0 0 30 18" fill="none" aria-hidden="true"><path className="ui-agent-thinking__infinity-track" d="M15 9C10 1 1 1 1 9s9 8 14 0c5-8 14-8 14 0s-9 8-14 0" pathLength="100" /><path className="ui-agent-thinking__infinity-head" d="M15 9C10 1 1 1 1 9s9 8 14 0c5-8 14-8 14 0s-9 8-14 0" pathLength="100" /></svg>;
  return <span className="ui-agent-thinking__orb"><i /><i /><i /></span>;
}

export function AgentThinking({ variant = 'wave', label = 'Thinking', active = true, showTimer = true, shimmer = true, tone = 'subtle', className }: AgentThinkingProps) {
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    if (!active || !showTimer) return;
    const start = performance.now();
    const timer = window.setInterval(() => setElapsed((performance.now() - start) / 1000), 100);
    return () => window.clearInterval(timer);
  }, [active, showTimer]);

  return <div className={cx('ui-agent-thinking', className)} data-variant={variant} data-active={active} data-tone={tone} role="status" aria-live="polite"><span className="ui-agent-thinking__indicator" aria-hidden="true"><ThinkingIndicator variant={variant} /></span><span className={cx('ui-agent-thinking__label', shimmer && active && 'ui-agent-thinking__label--shimmer')}>{active ? label : 'Ready'}</span>{active && showTimer && <time aria-hidden="true">{elapsed.toFixed(1)}s</time>}</div>;
}

'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { RiArrowDownSLine, RiLightbulbLine, RiRefreshLine, RiSearchLine } from '@remixicon/react';
import { AgentThinking } from '@/components/blocks/agent-thinking/agent-thinking';
import { SocialMark, type SocialProvider } from '@/components/base/social-button/social-button';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type SearchSource = {
  id: string;
  title: string;
  url?: string;
  href?: string;
  domain?: string;
  description?: string;
  brand?: SocialProvider;
  icon?: IconComponent;
};

export type SearchStep = {
  id: string;
  label?: string;
  query?: string;
  meta?: string;
  brand?: SocialProvider;
  icon?: IconComponent;
  heading?: boolean;
  dwell?: number;
  status?: 'searching' | 'complete';
  sources?: SearchSource[];
};

export type WebSearchProps = {
  steps: SearchStep[];
  title?: string;
  startDelay?: number;
  stepInterval?: number;
  /** Kept for existing consumers. Prefer stepInterval. */
  streamIntervalMs?: number;
  /** Number of visible rows. A step with sources counts as two rows. */
  revealed?: number;
  working?: string | false;
  onComplete?: () => void;
  onRunAgain?: () => void;
  className?: string;
};

const revealFrom = { opacity: 0, height: 0, y: 6, filter: 'blur(4px)' };
const revealTo = { opacity: 1, height: 'auto', y: 0, filter: 'blur(0px)' };
const revealTransition = { duration: 0.34, ease: [0.2, 0.75, 0.25, 1] as const };

function sourceDomain(source: SearchSource) {
  if (source.domain) return source.domain;
  try { return new URL(source.href ?? source.url ?? '').hostname; } catch { return ''; }
}

function sourceBrand(source: SearchSource): SocialProvider | undefined {
  if (source.brand) return source.brand;
  const domain = sourceDomain(source);
  if (domain.includes('reddit.')) return 'reddit';
  if (domain.includes('linkedin.')) return 'linkedin';
  if (domain.includes('github.')) return 'github';
  if (domain.includes('figma.')) return 'figma';
  if (domain.includes('notion.')) return 'notion';
  if (domain.includes('google.')) return 'google';
  if (domain.includes('x.com') || domain.includes('twitter.')) return 'x';
  return undefined;
}

function SourceMark({ source }: { source: SearchSource }) {
  const Icon = source.icon;
  return <span className="ui-web-search__mark" title={`${source.title}${sourceDomain(source) ? ` · ${sourceDomain(source)}` : ''}`}>
    {Icon ? <Icon size={13} aria-hidden /> : <SocialMark provider={sourceBrand(source)} size={13} />}
  </span>;
}

function StepIcon({ step }: { step: SearchStep }) {
  if (step.icon) { const Icon = step.icon; return <Icon size={16} aria-hidden />; }
  if (step.brand) return <SocialMark provider={step.brand} size={16} />;
  return step.heading ? <RiSearchLine size={16} aria-hidden /> : <RiLightbulbLine size={16} aria-hidden />;
}

export function WebSearch({
  steps,
  title,
  startDelay = 100,
  stepInterval,
  streamIntervalMs,
  revealed,
  working = 'Working',
  onComplete,
  onRunAgain,
  className,
}: WebSearchProps) {
  const reducedMotion = useReducedMotion();
  const interval = stepInterval ?? streamIntervalMs ?? 900;
  const heading = useMemo<SearchStep>(() => steps[0]?.heading ? steps[0] : { id: 'search-heading', label: title ?? `Ran ${steps.filter(step => step.query || step.brand || step.sources?.length).length} searches`, heading: true, dwell: interval }, [steps, title, interval]);
  const trail = useMemo(() => steps[0]?.heading ? steps.slice(1) : steps, [steps]);
  const rows = useMemo(() => [
    { id: heading.id, after: heading.dwell ?? interval },
    ...trail.flatMap(step => [
      { id: step.id, after: step.sources?.length ? 520 : step.dwell ?? interval },
      ...(step.sources?.length ? [{ id: `${step.id}-sources`, after: step.dwell ?? interval }] : []),
    ]),
  ], [heading.id, heading.dwell, interval, trail]);
  const totalUnits = rows.length;
  const [internalRevealed, setInternalRevealed] = useState(0);
  const [finished, setFinished] = useState(false);
  const [openSources, setOpenSources] = useState<string[]>([]);
  const completeRef = useRef(false);
  const onCompleteRef = useRef(onComplete);
  onCompleteRef.current = onComplete;

  useEffect(() => {
    if (revealed !== undefined) {
      setFinished(revealed >= totalUnits);
      return;
    }
    if (reducedMotion) {
      setInternalRevealed(totalUnits);
      setFinished(true);
      return;
    }
    setInternalRevealed(0);
    setFinished(false);
    let timer: number;
    let shown = 0;
    const showNext = () => {
      shown += 1;
      setInternalRevealed(shown);
      if (shown >= totalUnits) {
        timer = window.setTimeout(() => setFinished(true), Math.min(rows[shown - 1]?.after ?? interval, 1200));
      } else {
        timer = window.setTimeout(showNext, rows[shown - 1]?.after ?? interval);
      }
    };
    timer = window.setTimeout(showNext, Math.max(0, startDelay));
    return () => window.clearTimeout(timer);
  }, [interval, reducedMotion, revealed, rows, startDelay, totalUnits]);

  const visibleUnits = Math.max(0, Math.min(totalUnits, revealed ?? internalRevealed));
  const isFinished = revealed !== undefined ? visibleUnits >= totalUnits : finished;
  useEffect(() => {
    if (!isFinished) { completeRef.current = false; return; }
    if (completeRef.current) return;
    completeRef.current = true;
    onCompleteRef.current?.();
  }, [isFinished]);

  let cursor = 1;
  return <div className={cx('ui-web-search', className)} role="group" aria-label={title ?? heading.label ?? 'Web search activity'}>
    <AnimatePresence initial={false}>
      {visibleUnits > 0 && <motion.div className="ui-web-search__heading" key={heading.id} initial={reducedMotion ? false : revealFrom} animate={revealTo} exit={revealFrom} transition={reducedMotion ? { duration: 0 } : revealTransition}>
        <StepIcon step={heading} />
        <span>{title ?? heading.label}</span>
      </motion.div>}
    </AnimatePresence>

    <ol className="ui-web-search__steps" aria-live="polite">
      <AnimatePresence initial={false}>
        {trail.map(step => {
          const stepUnit = ++cursor;
          const sourceUnit = step.sources?.length ? ++cursor : 0;
          if (visibleUnits < stepUnit) return null;
          const sourcesVisible = sourceUnit > 0 && visibleUnits >= sourceUnit;
          const isActive = !isFinished && visibleUnits === stepUnit;
          const sourceOpen = openSources.includes(step.id);
          return <motion.li className="ui-web-search__step" key={step.id} initial={reducedMotion ? false : revealFrom} animate={revealTo} exit={revealFrom} transition={reducedMotion ? { duration: 0 } : revealTransition}>
            <div className="ui-web-search__row" data-active={isActive || step.status === 'searching' || undefined}>
              <span className="ui-web-search__icon"><StepIcon step={step} /></span>
              <span className="ui-web-search__label">{step.label ?? step.query}{step.label && step.query && <code>{step.query}</code>}</span>
              {(step.meta || step.sources?.length) && <span className="ui-web-search__meta">{step.meta ?? `${step.sources?.length} results`}</span>}
            </div>
            <AnimatePresence initial={false}>
              {sourcesVisible && <motion.div className="ui-web-search__source-branch" initial={reducedMotion ? false : revealFrom} animate={revealTo} exit={revealFrom} transition={reducedMotion ? { duration: 0 } : revealTransition}>
                <button type="button" className="ui-web-search__source-trigger" aria-expanded={sourceOpen} aria-label={`Sources for ${step.label ?? step.query}`} onClick={() => setOpenSources(current => current.includes(step.id) ? current.filter(id => id !== step.id) : [...current, step.id])}>
                  <span>Sources</span>
                  <span className="ui-web-search__marks" aria-hidden>
                    {step.sources?.slice(0, 6).map(source => <SourceMark key={source.id} source={source} />)}
                    {(step.sources?.length ?? 0) > 6 && <span className="ui-web-search__mark ui-web-search__mark--extra">+{(step.sources?.length ?? 0) - 6}</span>}
                  </span>
                  <RiArrowDownSLine size={16} aria-hidden />
                </button>
                <AnimatePresence initial={false}>
                  {sourceOpen && <motion.ul className="ui-web-search__source-links" initial={reducedMotion ? false : { height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: reducedMotion ? 0 : 0.27, ease: [0.2, 0.75, 0.25, 1] }}>
                    {step.sources?.map(source => {
                      const content = <><SourceMark source={source} /><span className="ui-web-search__source-title">{source.title}</span><small>{sourceDomain(source)}</small></>;
                      const href = source.href ?? source.url;
                      return <li key={source.id}>{href ? <a href={href} target="_blank" rel="noopener noreferrer" title={source.description}>{content}</a> : <span className="ui-web-search__source-static" title={source.description}>{content}</span>}</li>;
                    })}
                  </motion.ul>}
                </AnimatePresence>
              </motion.div>}
            </AnimatePresence>
          </motion.li>;
        })}
      </AnimatePresence>
    </ol>

    <AnimatePresence initial={false}>
      {!isFinished && working !== false && <motion.div key="working" className="ui-web-search__tail" initial={reducedMotion ? false : revealFrom} animate={revealTo} exit={revealFrom} transition={reducedMotion ? { duration: 0 } : revealTransition}><AgentThinking variant="stars" label={working} /></motion.div>}
      {isFinished && onRunAgain && <motion.button key="restart" type="button" className="ui-web-search__restart" onClick={onRunAgain} initial={reducedMotion ? false : revealFrom} animate={revealTo} exit={revealFrom} transition={reducedMotion ? { duration: 0 } : revealTransition}><RiRefreshLine size={16} aria-hidden />Run again</motion.button>}
    </AnimatePresence>
  </div>;
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});
